diff --git a/fs/io_uring.c b/fs/io_uring.c
index 8eb7386a3251..51d2021d89a3 100644
--- a/fs/io_uring.c
+++ b/fs/io_uring.c
@@ -1643,13 +1643,12 @@ static __cold void io_queue_deferred(struct io_ring_ctx *ctx)
 static __cold void io_flush_timeouts(struct io_ring_ctx *ctx)
 	__must_hold(&ctx->completion_lock)
 {
+	struct io_kiocb *req, *tmp;
 	u32 seq = ctx->cached_cq_tail - atomic_read(&ctx->cq_timeouts);

 	spin_lock_irq(&ctx->timeout_lock);
-	while (!list_empty(&ctx->timeout_list)) {
+	list_for_each_entry_safe(req, tmp, &ctx->timeout_list, timeout.list) {
 		u32 events_needed, events_got;
-		struct io_kiocb *req = list_first_entry(&ctx->timeout_list,
-						struct io_kiocb, timeout.list);

 		if (io_is_timeout_noseq(req))
 			break;
@@ -1666,7 +1665,6 @@ static __cold void io_flush_timeouts(struct io_ring_ctx *ctx)
 		if (events_got < events_needed)
 			break;

-		list_del_init(&req->timeout.list);
 		io_kill_timeout(req, 0);
 	}
 	ctx->cq_last_tm_flush = seq;
